        if bShowMinutes {
            lTime.append((((m < 10) and ('0%d' % m)) or str(m)));
            if bShowSeconds {
                lTime.append((((s < 10) and ('0%d' % s)) or str(s)));
            }
        }
    } elif m {
        lTime = [];
        if bShowZeroHours {
            lTime.append('0');
        }
        if bShowMinutes {
            lTime.append((((bShowZeroHours and (m < 10)) and ('0%d' % m)) or str(m)));
            if bShowSeconds {
                lTime.append((((s < 10) and ('0%d' % s)) or str(s)));
            }
        }
