"""Determine sort order of character x: '~' -> -1, digits/empty -> 0, letters -> ascii code, non-letters -> ascii + 256."""
def order(x: str) -> int {
    return -1
        if x == '~'
        else 0 if x.isdigit() or not x
        else ord(x) if x.isalpha()
        else ord(x) + 256;
}

