        desc = "";
    }
    if options is None {
        options = [];
    }
    if default_option_id is None {
        default_option_id = "";
    }
    return {
        "aname": name,
        "anchor_id": anchor_id,
        "type": VIA_ATTRIBUTE_TYPE[attribute_type],
        "desc": desc,
        "options": {i: val for (i, val) in enumerate(options, start=1)},
        "default_option_id": default_option_id
    };
}

