"""Return the value reached by walking `keys` through nested dicts in `d`, or `default_value` if any key along the path is missing."""
def getdeepattr(d: dict[str, object], keys: list[str] | tuple[str, ...], default_value: object = None) -> object {
    current = d;
    for key in keys {
        if key not in current {
            return default_value;
        }
        current = current[key];
    }
    return current;
}

